from openai.types.chat import ChatCompletion

from areal.api import AsyncRewardWrapper


def math_reward_fn(completions: str, answer: str) -> float:
    ans = parse(completions)
    gold = parse(answer)
    return float(verify(ans, gold))


class MathAgent:
    def __init__(self, **kwargs):
        self.kwargs = kwargs.copy()
        max_new_tokens = self.kwargs.pop("max_new_tokens", None)
        self.kwargs.pop("max_turns", None)
        if max_new_tokens is not None and "max_tokens" not in self.kwargs:
            self.kwargs["max_tokens"] = max_new_tokens
        else:
            self.kwargs.pop("max_tokens", None)
        self._reward_fn = AsyncRewardWrapper(math_reward_fn)

    async def run(self, data: dict, **extra_kwargs):
        http_client = extra_kwargs.get("http_client", None)
        base_url = extra_kwargs.get("base_url", None) or os.getenv("OPENAI_BASE_URL")
        api_key = extra_kwargs.get("api_key", None) or os.getenv("OPENAI_API_KEY")
        client = AsyncOpenAI(
            base_url=base_url, api_key=api_key, http_client=http_client, max_retries=0
        )
        messages = data.get("messages_chat") or data["messages"]
        if isinstance(messages, str):
            messages = [{"role": "user", "content": messages}]
        comp: ChatCompletion = await client.chat.completions.create(
            messages=messages, model="default", extra_body={"chat_template_kwargs": {"enable_thinking": False}}, **self.kwargs
        )

        return await self._reward_fn(
            completions=comp.choices[0].message.content, answer=data["answer"]
        )


class MultiTurnMathAgent:
    def __init__(self, max_turns: int = 8, **kwargs):
        self.max_turns = max_turns
        self.kwargs = kwargs.copy()
        max_new_tokens = self.kwargs.pop("max_new_tokens", None)
        if max_new_tokens is not None and "max_tokens" not in self.kwargs:
            self.kwargs["max_tokens"] = max_new_tokens
        else:
            self.kwargs.pop("max_tokens", None)
        self._reward_fn = AsyncRewardWrapper(math_reward_fn)

    async def run(self, data: dict, **extra_kwargs):
        http_client = extra_kwargs.get("http_client", None)
        base_url = extra_kwargs.get("base_url", None) or os.getenv("OPENAI_BASE_URL")
        api_key = extra_kwargs.get("api_key", None) or os.getenv("OPENAI_API_KEY")
        messages = list(data.get("messages_chat") or data["messages"])
        if isinstance(messages, str):
            messages = [{"role": "user", "content": messages}]
        else:
            messages = [m for m in messages]
        rewards = {}
        client = AsyncOpenAI(
            base_url=base_url, api_key=api_key, http_client=http_client, max_retries=0
        )
        for _ in range(self.max_turns):
            response: ChatCompletion = await client.chat.completions.create(
                messages=messages,
                extra_body={"chat_template_kwargs": {"enable_thinking": False}},
                model="default",
                **self.kwargs,
            )
            message = response.choices[0].message
            messages.append(message.model_dump(exclude_none=True))
            reward = await self._reward_fn(
                completions=message.content, answer=data["answer"]
            )
            rewards[response.id] = reward
            if reward == 1:
                break
            else:
                messages.append(
                    {
                        "role": "user",
                        "content": "Your answer is either wrong or not parsable to the reward function. You may misunderstand the original question. "
                        "Please carefully read the original question, check the previous errors, and try to answer it again.",
                    }
                )
        return rewards


@function_tool
def add(a: float, b: float) -> float:
    """Add two numbers."""
    return a + b


@function_tool
def subtract(a: float, b: float) -> float:
    """Subtract two numbers."""
    return a - b


@function_tool
def multiply(a: float, b: float) -> float:
    """Multiply two numbers."""
    return a * b


@function_tool
def divide(a: float, b: float) -> float:
    """Divide two numbers."""
    if b == 0:
        raise ValueError("Division by zero is not allowed.")
    return a / b


@function_tool
def power(a: float, b: float) -> float:
    """Raise a to the power of b."""
    return a**b


@function_tool
def sqrt(a: float) -> float:
    """Calculate the square root of a number."""
    if a < 0:
        raise ValueError("Cannot compute square root of a negative number.")
    return a**0.5


class MathToolAgent:
    def __init__(self, **kwargs):
        self.kwargs = kwargs.copy()
        self.kwargs.pop("max_tokens", None)
        self.kwargs.pop("max_turns", None)
        self._reward_fn = AsyncRewardWrapper(math_reward_fn)

    async def run(self, data: dict, **extra_kwargs):
        http_client = extra_kwargs.get("http_client", None)
        base_url = extra_kwargs.get("base_url", None) or os.getenv("OPENAI_BASE_URL")
        api_key = extra_kwargs.get("api_key", None) or os.getenv("OPENAI_API_KEY")
        client = AsyncOpenAI(
            base_url=base_url, api_key=api_key, http_client=http_client, max_retries=0
        )
        content = data["messages"][-1]["content"]
        run_config = RunConfig(
            model_provider=OpenAIProvider(openai_client=client),
            model="default",
            tracing_disabled=True,
            model_settings=ModelSettings(**self.kwargs),
        )
        agent = Agent(
            name="RLVR Math with Calculator",
            instructions="Answer the user's math questions using the available calculator tools. Don't give the answer directly, you must use tools to do the mathematical calculation.",
            tools=[
                add,
                subtract,
                multiply,
                divide,
                power,
                sqrt,
            ],
        )
        session = SQLiteSession("math")
        result = await OpenAIRunner.run(
            agent, input=content, session=session, run_config=run_config
        )

        return await self._reward_fn(
            completions=result.final_output, answer=data["answer"]
        )

def _evaluate_fn(
    self,
    eval_workflow: WorkflowLike,
    eval_workflow_kwargs,
):
    if self.actor.is_data_parallel_head():
        cnt = 0
        for data in self.valid_dataloader:
            for item in data:
                self.eval_rollout.submit(
                    item,
                    eval_workflow,
                    eval_workflow_kwargs,
                    group_size=self.config.eval_gconfig.n_samples,
                    is_eval=True,
                    reward_normalization=False,
                    drop_incomplete_group=False,
                )
                cnt += 1
        self.eval_rollout.wait(cnt, timeout=None)

    if not is_single_controller():
        dist.barrier(group=self.actor.cpu_group)
        current_platform.synchronize()

def _evaluate(
    self,
    eval_workflow: WorkflowLike | None,
    eval_workflow_kwargs,
    epoch: int,
    epoch_step: int,
    global_step: int,
):
    if (
        self.eval_rollout is None
        or self.valid_dataloader is None
        or eval_workflow is None
    ):
        return
    self.evaluator.evaluate(
        functools.partial(
            self._evaluate_fn,
            eval_workflow=eval_workflow,
            eval_workflow_kwargs=eval_workflow_kwargs,
        ),
        epoch,
        epoch_step,
        global_step,
    )
    if not is_single_controller():
        dist.barrier(group=self.actor.cpu_group)
        current_platform.synchronize()

def _export_and_commit_stats(self, epoch: int, epoch_step: int, global_step: int):
    # Upload statistics to the logger (e.g., wandb)
    stats = self.actor.export_stats()
    stats.update(self.rollout.export_stats())
    if self.eval_rollout is not None:
        stats.update(self.eval_rollout.export_stats())
    self.stats_logger.commit(epoch, epoch_step, global_step, stats)

    if not is_single_controller():
        dist.barrier(group=self.actor.cpu_group)
        current_platform.synchronize()

def _validate_cfg(self):
    """validate config for incompatible settings before weight initialization, to avoid wasted resources on spawning workers and loading models."""
    rollout_backend = self.rollout_alloc.backend
    actor_backend = self.actor_alloc.backend
    requires_train_engine_offload = any(
        (
            self._should_offload_rollout,
            self._should_offload_actor,
            self._should_offload_critic,
            self._should_offload_ref,
            self._should_offload_teacher,
        )
    )

    if requires_train_engine_offload and not self.config.enable_offload:
        raise ValueError(
            "enable_offload must be True when colocation scheduling or train-engine "
            "offload is enabled. Please set enable_offload=True."
        )

    if self._is_actor_rollout_colocated(
        self.config
    ) and self.config.actor.weight_update_mode not in ("disk", "awex"):
        raise ValueError(
            "weight_update_mode must be 'disk' or 'awex' when colocation "
            "scheduling is enabled. Please set actor.weight_update_mode "
            "to one of them."
        )

    if self._is_v1_awex_colocate(self.config):
        if actor_backend != "megatron":
            raise ValueError(
                "weight_update_mode='awex' requires Megatron actor training "
                f"backend, got {actor_backend!r}."
            )
        if rollout_backend != "sglang":
            raise ValueError(
                "weight_update_mode='awex' requires SGLang rollout backend, "
                f"got {rollout_backend!r}."
            )

    if rollout_backend == "vllm" and self.config.rollout.return_routed_experts:
        raise ValueError(
            "return_routed_experts is only supported with SGLang backend. "
            "Please disable return_routed_experts or switch to SGLang backend."

